from rest_framework_jwt.views import ObtainJSONWebToken
from .models import CustomerBillingAccount

def custom_jwt_response_payload_handler(token, user=None, request=None):
    requested_account_id = request.GET.get('account_id') if request else None
    billing_data = {}
    if requested_account_id and user:
        # Enforce that billing account strictly belongs to authenticating user
        account = CustomerBillingAccount.objects.filter(id=requested_account_id, owner=user).first()
        if account:
            billing_data = {
                'account_id': account.id,
                'account_number': account.account_number,
                'tax_identifier': account.tax_identifier,
                'credit_limit': str(account.credit_limit)
            }

    return {
        'token': token,
        'user_id': user.id if user else None,
        'billing_profile': billing_data
    }

class LoginTokenView(ObtainJSONWebToken):
    pass
